  width: 100%;
  max-width: 520px;
}

.page-title {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
}

/* ── Image card ── */
.image-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.image-preview {
  width: 100%;
  aspect-ratio: 16 / 10;
  object-fit: cover;
  display: block;
  background: var(--surface-2);
  position: relative;
}

/* Placeholder gradient image */
.image-preview-placeholder {
  width: 100%;
  aspect-ratio: 16 / 10;
  background:
    linear-gradient(135deg,
      #1e2340 0%,
      #2a1f45 25%,
      #1a2855 50%,
      #0e2038 75%,
      #1c2640 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.image-preview-placeholder::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 50% at 30% 40%, rgba(91, 106, 240, 0.25) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 75% 65%, rgba(168, 85, 247, 0.2) 0%, transparent 60%);
}

.placeholder-icon {
  position: relative;
  color: rgba(255, 255, 255, 0.15);
}

.placeholder-icon svg {
  width: 64px;
  height: 64px;
}

.card-info {
  padding: 16px 20px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.card-meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.card-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.card-date {
  font-size: 0.78rem;
  color: var(--text-muted);
}

/* ── Delete trigger button ── */
.btn-delete.trigger {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 16px;
  background: var(--danger-light);
  color: var(--danger);
  border: 1px solid rgba(224, 82, 82, 0.25);
  border-radius: 8px;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.18s, border-color 0.18s, transform 0.12s;
  white-space: nowrap;
  flex-shrink: 0;
}

.btn-delete.trigger:hover {
  background: rgba(224, 82, 82, 0.22);
  border-color: rgba(224, 82, 82, 0.45);
}

.btn-delete.trigger:active {
  transform: scale(0.97);
}

/* ── Modal overlay ── */
.modal-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: var(--overlay);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  z-index: 100;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.modal-overlay.open {
  display: flex;
}

/* ── Modal dialog ── */
.modal {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  width: 100%;
  max-width: 420px;
  padding: 32px 28px 28px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  animation: modal-in 0.22s cubic-bezier(0.34, 1.2, 0.64, 1) both;
}

@keyframes modal-in {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.modal-overlay:not(.open) .modal {
  animation: none;
}

/* ── Modal header ── */
.modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.modal-icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: var(--danger-light);
  border: 1px solid rgba(224, 82, 82, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--danger);
}

.modal-close {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text-muted);
  padding: 4px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color 0.15s, background 0.15s;
  margin-top: -4px;
}

.modal-close:hover {
  color: var(--text);
  background: var(--surface-2);
}

/* ── Modal body ── */
.modal-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.modal-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text);
  line-height: 1.3;
}

.modal-description {
  font-size: 0.88rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* ── Image thumbnail in dialog ── */
.modal-thumbnail {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 14px;
}

.modal-thumb-img {
  width: 42px;
  height: 42px;
  border-radius: 6px;
  background: linear-gradient(135deg, #1e2340, #2a1f45);
  flex-shrink: 0;
}

.modal-thumb-name {
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text);
}

.modal-thumb-size {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* ── Modal actions ── */
.modal-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 9px 20px;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
  border: 1px solid transparent;
}

.btn:active {
  transform: scale(0.97);
}

.btn-cancel {
  background: var(--surface-2);
