  border-color: var(--border);
}

.btn-cancel:hover {
  color: var(--text);
  background: #2a2f4a;
  border-color: #3a4060;
}

.btn-confirm-delete {
  background: var(--danger);
  color: #fff;
  border-color: var(--danger);
}

.btn-confirm-delete:hover {
  background: var(--danger-hover);
  border-color: var(--danger-hover);
}
