.image-preview-placeholder {
  width: 100%;
  aspect-ratio: 16 / 10;
  background:
    linear-gradient(135deg,
      #1e2340 0%,
      #2a1f45 25%,
      #1a2855 50%,
      #0e2038 75%,
      #1c2640 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.image-preview-placeholder::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 50% at 30% 40%, rgba(91, 106, 240, 0.25) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 75% 65%, rgba(168, 85, 247, 0.2) 0%, transparent 60%);
}

.placeholder-icon {
  position: relative;
  color: rgba(255, 255, 255, 0.15);
}

.placeholder-icon svg {
  width: 64px;
  height: 64px;
}

.card-info {
  padding: 16px 20px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.card-meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.card-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.card-date {
  font-size: 0.78rem;
